<script setup>
import { ref, computed, onBeforeUnmount } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { account } from '../account.js';
const route=useRoute(), router=useRouter();
const screen=ref('login'), method=ref('code'), credential=ref(''), nickname=ref(''), agreed=ref(false), error=ref(''), message=ref(''), seconds=ref(0), terms=ref();
let timer;
const title=computed(()=>screen.value==='register'?'创建你的演示资料':screen.value==='reset'?'找回演示登录方式':'欢迎回来');
function change(value){screen.value=value;error.value='';message.value='';credential.value='';}
function code(){message.value='演示验证码：123456（没有发送短信）';seconds.value=30;clearInterval(timer);timer=setInterval(()=>{seconds.value--;if(seconds.value<=0)clearInterval(timer)},1000)}
function enter(){const next=route.query.redirect;router.push(typeof next==='string'&&/^\/(interviews|growth|library|me)(\/|$)/.test(next)?next:'/')}
function submit(){error.value='';try{if(screen.value==='register')account.call('register',{nickname:nickname.value,code:credential.value,agreed:agreed.value});else account.call('login',{method:method.value,credential:credential.value,agreed:agreed.value});enter()}catch(e){error.value=e.message}}
onBeforeUnmount(()=>clearInterval(timer));
</script>
<template><div class="auth-studio"><section class="auth-brand"><RouterLink to="/" class="auth-logo"><span class="brand-mark">m.</span><strong>面试精灵<small>INTERVIEW STUDIO</small></strong></RouterLink><div><p class="eyebrow">YOUR NEXT CHAPTER</p><h1>每一次练习，<br>都离理想更近。</h1><p>准备、表达、复盘，找到你的成长节奏。</p></div><img class="fairy-mascot" src="/images/interview-fairy-transparent.png" alt="绿色光之精灵"/></section><section class="auth-form"><span class="badge">DEMO 演示</span><img class="auth-mobile-sprite fairy-mascot" src="/images/interview-fairy-transparent.png" alt=""/><h1>{{title}}</h1><p class="muted">{{screen==='reset'?'这里使用公开的演示凭证，无需修改真实密码。':'继续你的面试练习。'}}</p><template v-if="screen==='reset'"><div class="notice"><p>演示验证码：<b>123456</b></p><p>演示密码：<b>demo123456</b></p><p>不发送短信，不修改真实账户。</p></div><button class="button primary wide" @click="change('login')">返回登录</button></template><form v-else @submit.prevent="submit"><div v-if="screen==='login'" class="tabs"><button type="button" :class="{active:method==='code'}" @click="method='code';credential=''">验证码登录</button><button type="button" :class="{active:method==='password'}" @click="method='password';credential=''">密码登录</button></div><label v-if="screen==='register'">昵称<input v-model="nickname" maxlength="20" placeholder="怎么称呼你？" required/></label><label>演示账户<input value="demo · 本地体验空间" readonly aria-label="演示账户"/></label><label>{{method==='code'||screen==='register'?'演示验证码':'演示密码'}}<div class="code-input"><input v-model="credential" :aria-label="method==='password'&&screen!=='register'?'演示密码':'演示验证码'" :type="method==='password'&&screen!=='register'?'password':'text'" :placeholder="method==='password'&&screen!=='register'?'demo123456':'123456'" autocomplete="off" required/><button v-if="method==='code'||screen==='register'" type="button" class="text-link" :disabled="seconds>0" @click="code">{{seconds?seconds+' 秒':'获取演示码'}}</button></div></label><p v-if="message" class="notice" role="status">{{message}}</p><label class="check-label"><input type="checkbox" v-model="agreed"/>我了解这是本地演示，不是真实账号注册</label><button type="button" class="text-link" @click="terms.showModal()">查看演示与数据说明</button><p v-if="error" class="error" role="alert">{{error}}</p><button class="button primary wide" type="submit">{{screen==='register'?'创建演示资料':'登录演示空间'}}</button><div class="section-heading"><button type="button" class="text-link" @click="change(screen==='register'?'login':'register')">{{screen==='register'?'已有资料，返回登录':'创建演示资料'}}</button><button type="button" class="text-link" @click="change('reset')">忘记密码？</button></div></form><div class="auth-divider">或</div><button class="button secondary wide" @click="enter">先体验 Demo</button><p class="small muted">无需提供手机号或真实密码。资料与练习保存在当前浏览器。</p><RouterLink to="/resumes/real" class="text-link">登录真实账户与简历库 →</RouterLink></section><dialog ref="terms"><h2>演示与数据说明</h2><p>本空间只模拟登录状态，不提供真实身份验证。公开演示凭证不会保护本地记录，请勿在公用设备留下个人信息。</p><p>头像、昵称与训练记录保存在当前浏览器；不会同步到真实账户。所有 AI 与语音评分都标明演示来源。</p><button class="button primary" @click="terms.close()">我知道了</button></dialog></div></template>
